// รับค่า nowString จาก global
var nowString = global.get("now").nowString; // เช่น "วัน ศุกร์ ที่ 2025-06-27 เวลา 00:14:26"

// รับ period จาก environment
var period = env.get("period");

// ดึงชื่อวันและเวลาออกจาก nowString
var match = nowString.match(/วัน\s(.+?)\sที่\s.*เวลา\s(\d{2}:\d{2}:\d{2})/);
var message = "";

if (!match) {
    node.error("ไม่สามารถแยกข้อมูลจาก nowString ได้");
    return null;
}

var dayName = match[1]; // เช่น "ศุกร์"
var timeNow = match[2]; // เช่น "00:14:26"

// ตรวจสอบว่าวันนี้เปิดหรือไม่
var isDayAllowed = period.date.some(d => d[dayName] === true);

if (!isDayAllowed) {
    message = `❌ วันนี้ (${dayName}) ไม่อยู่ในวันกำหนด`;
    msg.payload = message;
    msg.inRange = false;
    node.status({ fill: "green", shape: "dot", text: message });
    return msg;
}

// ตรวจสอบว่าช่วงเวลาไหนที่ตรง
let currentRange = period.time.find(range => {
    return range.start <= timeNow && timeNow <= range.to;
});

if (currentRange) {
    message = `✅ ตอนนี้ (${timeNow}) อยู่ในช่วง ${currentRange.start} ถึง ${currentRange.to}`;
    msg.payload = message
    msg.inRange = true;
    var remaining = getTimeRemaining(timeNow, currentRange.to);
    msg.text = `${currentRange.start}น. ถึง ${currentRange.to}น.<br>
    [${remaining.hours}ชั่วโมง ${remaining.minutes}นาที ${remaining.seconds}วินาที]`;
    node.status({ fill: "blue", shape: "dot", text: message });
} else {
    message = `❌ ตอนนี้ (${timeNow}) ไม่อยู่ในช่วงเวลาใด`;
    msg.payload = message;
    msg.inRange = false;
    node.status({ fill: "green", shape: "dot", text: message });
}

return msg;



function timeStringToSeconds(timeStr) {
    const [h, m, s] = timeStr.split(":").map(Number);
    return h * 3600 + m * 60 + s;
}

function getTimeRemaining(timenow, currentTo) {
    const nowSec = timeStringToSeconds(timenow);
    const toSec = timeStringToSeconds(currentTo);

    let diff = toSec - nowSec;
    if (diff < 0) diff = 0;

    const hours = Math.floor(diff / 3600);
    const minutes = Math.floor((diff % 3600) / 60);
    const seconds = diff % 60;
    return {
        "hours": hours,
        "minutes": minutes,
        "seconds": seconds
    }
}

